import { useEffect, useState } from "react";
import { Check, Loader2 } from "lucide-react";
import { cleanQuoteNumber } from "@/lib/vematEntities";
import { INPUT_CLS } from "./registerContext";

interface Props {
  /** Current number saved on the quote (null = not entered yet). */
  value: string | null;
  /** Saves the cleaned number (null clears it). Must throw on error. */
  onSave: (value: string | null) => Promise<void>;
  disabled?: boolean;
  ring?: string;
}

/** Inline field for the official quote number generated by Atlascom (typed by hand). */
export function AtlascomNumberField({ value, onSave, disabled, ring = "focus:border-sky-400 focus:ring-2 focus:ring-sky-100" }: Props) {
  const [text, setText] = useState(value ?? "");
  const [busy, setBusy] = useState(false);
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState<string | null>(null);
  useEffect(() => { setText(value ?? ""); }, [value]);

  const cleaned = cleanQuoteNumber(text);
  const changed = cleaned !== (value ?? null);

  async function save() {
    setBusy(true); setError(null); setSaved(false);
    try { await onSave(cleaned); setSaved(true); }
    catch (e) {
      const msg = (e as Error).message;
      setError(/duplicate|unique/i.test(msg) ? "This number is already used by another document." : msg);
    } finally { setBusy(false); }
  }

  return (
    <div>
      <div className="flex gap-2">
        <input
          className={`${INPUT_CLS} ${ring} font-mono`}
          value={text}
          onChange={(e) => { setText(e.target.value); setSaved(false); }}
          placeholder="DE26…"
          disabled={disabled || busy}
          aria-label="Quote number generated by Atlascom"
        />
        <button type="button" onClick={save} disabled={disabled || busy || !changed}
          className="shrink-0 inline-flex items-center gap-1.5 text-xs font-bold rounded-lg px-3 bg-zinc-900 text-white disabled:opacity-40">
          {busy ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : saved ? <Check className="w-3.5 h-3.5" /> : null} Save
        </button>
      </div>
      {error && <p className="text-xs text-red-600 mt-1">{error}</p>}
    </div>
  );
}
